package org.sleepwell.app;

import org.junit.Test;
import static org.junit.Assert.*;

public class AlarmVibrationTest {
    private static class Output implements AlarmVibration.Port {
        int starts,cancels;boolean available=true,throwStart,throwCancel;
        public boolean start(){starts++;if(throwStart)throw new IllegalStateException("start");return available;}
        public void cancel(){cancels++;if(throwCancel)throw new IllegalStateException("cancel");}
    }
    private static final class Fixture {
        long elapsed;boolean alive=true;int allocations,errors;final Output output=new Output();
        AlarmVibration create(long delay){return new AlarmVibration(delay,()->elapsed,()->alive,()->{allocations++;return output;},()->errors++);}
    }
    @Test public void immediateStartsOnceAndCloseCancelsOnce(){Fixture f=new Fixture();AlarmVibration owner=f.create(0);owner.tick(false);for(int n=0;n<20;n++){f.elapsed+=100;owner.tick(n%2==0);}assertEquals(1,f.allocations);assertEquals(1,f.output.starts);owner.close();owner.close();owner.tick(true);assertEquals(1,f.output.cancels);assertEquals(0,f.errors);}
    @Test public void delayedOutputDoesNotAllocateUntilTheExactBoundary(){Fixture f=new Fixture();AlarmVibration owner=f.create(60000);for(long elapsed:new long[]{0,100,50000,59999}){f.elapsed=elapsed;owner.tick(false);}assertEquals(0,f.allocations);f.elapsed=60000;owner.tick(false);assertEquals(1,f.output.starts);f.elapsed=120000;owner.tick(false);assertEquals(1,f.output.starts);}
    @Test public void restartedOwnerUsesOriginalOccurrenceElapsedTime(){Fixture first=new Fixture();AlarmVibration old=first.create(60000);first.elapsed=30000;old.tick(false);old.close();assertEquals(0,first.allocations);Fixture restarted=new Fixture();restarted.elapsed=59999;AlarmVibration current=restarted.create(60000);current.tick(false);assertEquals(0,restarted.allocations);restarted.elapsed=60000;current.tick(false);assertEquals(1,restarted.output.starts);current.close();Fixture late=new Fixture();late.elapsed=80000;AlarmVibration lateOwner=late.create(60000);lateOwner.tick(false);assertEquals(1,late.output.starts);assertEquals(1,restarted.output.cancels);}
    @Test public void backupBypassesDelayButCannotStartAnAlreadyPlayingOwnerAgain(){Fixture f=new Fixture();AlarmVibration owner=f.create(120000);owner.tick(false);assertEquals(0,f.allocations);owner.tick(true);owner.tick(true);assertEquals(1,f.output.starts);}
    @Test public void livenessLossBeforeAndAfterStartClosesPermanently(){Fixture waiting=new Fixture();AlarmVibration old=waiting.create(1000);waiting.alive=false;old.tick(true);waiting.alive=true;old.tick(true);assertEquals(0,waiting.allocations);Fixture playing=new Fixture();AlarmVibration current=playing.create(0);current.tick(false);playing.alive=false;current.tick(false);playing.alive=true;current.tick(true);assertEquals(1,playing.output.starts);assertEquals(1,playing.output.cancels);}
    @Test public void livenessIsRecheckedAfterLazyAllocationAndStart(){boolean[] alive={true};Output neverStarted=new Output();AlarmVibration old=new AlarmVibration(0,()->0,()->alive[0],()->{alive[0]=false;return neverStarted;},()->fail("Lost occurrence is cancellation, not a hardware error"));old.tick(false);assertEquals(0,neverStarted.starts);assertEquals(1,neverStarted.cancels);Output started=new Output(){public boolean start(){super.start();alive[0]=false;return true;}};alive[0]=true;AlarmVibration race=new AlarmVibration(0,()->0,()->alive[0],()->started,()->fail("Must simply cancel"));race.tick(false);assertEquals(1,started.starts);assertEquals(1,started.cancels);}
    @Test public void unavailableOrThrowingHardwareGetsOneAttemptAndOneError(){for(boolean throwsStart:new boolean[]{false,true}){Fixture f=new Fixture();f.output.available=false;f.output.throwStart=throwsStart;AlarmVibration owner=f.create(0);owner.tick(false);owner.tick(true);owner.close();assertEquals(1,f.allocations);assertEquals(1,f.output.starts);assertEquals(1,f.output.cancels);assertEquals(1,f.errors);}}
    @Test public void factoryAndReleaseFailuresAreBounded(){int[] attempts={0},errors={0};AlarmVibration failed=new AlarmVibration(0,()->0,()->true,()->{attempts[0]++;throw new IllegalStateException("factory");},()->{errors[0]++;throw new IllegalStateException("report");});failed.tick(false);failed.tick(true);assertEquals(1,attempts[0]);assertEquals(1,errors[0]);Fixture f=new Fixture();f.output.throwCancel=true;AlarmVibration owner=f.create(0);owner.tick(false);owner.close();owner.close();assertEquals(1,f.output.cancels);Fixture waiting=new Fixture();AlarmVibration unused=waiting.create(60000);unused.close();unused.tick(true);assertEquals(0,waiting.allocations);}
    @Test public void negativeElapsedCannotBypassAPositiveDelay(){Fixture f=new Fixture();f.elapsed=-1;AlarmVibration owner=f.create(1);owner.tick(false);assertEquals(0,f.allocations);f.elapsed=1;owner.tick(false);assertEquals(1,f.output.starts);}
    @Test public void policyPreservesLegacyImmediateDefaultAndDisablesQuietOrOptOut(){Alarm a=new Alarm(1);assertEquals(0,a.vibrationDelaySeconds);assertTrue(new AlarmWakePolicy(a).vibration);a.vibrationDelaySeconds=180;assertEquals(180000,new AlarmWakePolicy(a).vibrationDelayMillis);a.vibrate=false;assertFalse(new AlarmWakePolicy(a).vibration);for(int id:new int[]{0,-1,Integer.MIN_VALUE}){a.id=id;a.vibrate=true;AlarmWakePolicy quiet=new AlarmWakePolicy(a);assertFalse(quiet.vibration);assertEquals(0,quiet.vibrationDelayMillis);}a.id=1;a.vibrationDelaySeconds=Integer.MAX_VALUE;assertEquals(1440000,new AlarmWakePolicy(a).vibrationDelayMillis);assertEquals(Integer.MAX_VALUE,a.vibrationDelaySeconds);a.vibrationDelaySeconds=-1;assertEquals(0,new AlarmWakePolicy(a).vibrationDelayMillis);}
}
